/**
 * isElementOverflowing calculates if the element is overflowing and has scrollable content
 */
export const isElementOverflowing = (
  element: HTMLElement,
  direction: 'horizontal' | 'vertical' | 'both' = 'both',
) => {
  // http://jsfiddle.net/y8Y32/25/
  switch (direction) {
    case 'horizontal':
      return element.clientWidth !== element.scrollWidth;
    case 'vertical':
      return element.clientHeight !== element.scrollHeight;
    default:
      return (
        element.clientWidth !== element.scrollWidth &&
        element.clientHeight !== element.scrollHeight
      );
  }
};
